//! Tier 3, slice T3.1: sketch-based synthesis in the style of PCDC.
//!
//! A [`Sketch`] is a list of **classes**. A class has a size (how many rows it stands for) and one
//! axis entry per column: for a number column a value range with a density over it (a histogram),
//! for a category column a share per value. A row is generated by picking a class in proportion
//! to its size and then drawing every column independently from that class's axis entry. Inside a
//! class the columns are independent; dependencies between columns come only from the mix of
//! classes.
//!
//! [`propose`] builds a first sketch from the data (seeded k-means, classes under the minimum size
//! folded into the nearest one). The user may then change the sketch; [`synthesize_sketch`]
//! samples from whatever sketch it is given and measures the result against the original.
//!
//! No privacy guarantee. A proposed sketch is derived from the data: its class ranges end at real
//! values, so the sketch itself is to be handled like the data.

use super::numeric::Rng;
use super::{
    dropped_warnings, format_rows, metrics, prepare, round_to_observed, ColumnData, DroppedColumn,
    Preparation, Prepared, SynthesisReport, SynthesisResult, SynthesizeConfig, PRIVACY_STATEMENT,
    REPORT_VERSION,
};
use serde::{Deserialize, Serialize};
use std::collections::BTreeSet;
use triplex_core::{Error, Result};
use triplex_io::Sample;

pub const SKETCH_VERSION: u32 = 1;
pub const DEFAULT_CLASSES: usize = 4;
/// Prefilled value of the user's minimum class size.
pub const DEFAULT_MIN_CLASS_SIZE: usize = 20;
pub const DEFAULT_BINS: usize = 16;
/// An integer column with at most this many distinct values becomes a category axis, so it never
/// produces a value that did not occur (the same rule as the Bayesian network).
const SMALL_DISTINCT: usize = 20;
const KMEANS_ITERATIONS: usize = 50;
/// Fewest density bins of a number axis produced by merging two classes.
const MERGED_BINS: usize = 32;

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[serde(tag = "type", rename_all = "snake_case")]
pub enum ColumnKind {
    Numeric {
        #[serde(default)]
        integer: bool,
    },
    Categorical {
        values: Vec<String>,
    },
}

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct SketchColumn {
    pub name: String,
    #[serde(flatten)]
    pub kind: ColumnKind,
}

/// One class's entry on one axis.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[serde(tag = "type", rename_all = "snake_case")]
pub enum Axis {
    /// Values fall in `min..=max`; `density` holds one weight per equal-width bin of that range.
    Numeric {
        min: f64,
        max: f64,
        density: Vec<f64>,
        #[serde(default)]
        null_share: f64,
    },
    /// One weight per value of the column, in the column's order.
    Categorical {
        shares: Vec<f64>,
        #[serde(default)]
        null_share: f64,
    },
}

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct SketchClass {
    pub name: String,
    /// How many rows this class stands for; classes are drawn in proportion to it.
    pub size: usize,
    /// One entry per column of the sketch, in the same order.
    pub axes: Vec<Axis>,
}

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct Sketch {
    pub version: u32,
    pub columns: Vec<SketchColumn>,
    pub classes: Vec<SketchClass>,
}

/// What [`propose`] needs besides the shared settings.
#[derive(Debug, Clone)]
pub struct SketchConfig {
    /// Rows, seed, rare-category threshold and the rows and columns the user removed.
    pub base: SynthesizeConfig,
    /// Classes to look for.
    pub classes: usize,
    /// A user parameter: a class with fewer rows is folded into the nearest one.
    pub min_class_size: usize,
    /// Density bins per number axis.
    pub bins: usize,
}

impl Default for SketchConfig {
    fn default() -> Self {
        SketchConfig {
            base: SynthesizeConfig::default(),
            classes: DEFAULT_CLASSES,
            min_class_size: DEFAULT_MIN_CLASS_SIZE,
            bins: DEFAULT_BINS,
        }
    }
}

/// The classes of the sketch a table was generated from, for the report.
#[derive(Debug, Clone, PartialEq, Serialize)]
pub struct SketchSummary {
    pub classes: Vec<ClassSummary>,
}

#[derive(Debug, Clone, PartialEq, Serialize)]
pub struct ClassSummary {
    pub name: String,
    pub size: usize,
}

fn invalid(message: String) -> Error {
    Error::Validation(message)
}

fn weights_ok(weights: &[f64]) -> bool {
    !weights.is_empty()
        && weights.iter().all(|w| w.is_finite() && *w >= 0.0)
        && weights.iter().sum::<f64>() > 0.0
}

impl Sketch {
    /// Refuses a sketch that cannot be sampled from, naming the class and column at fault.
    pub fn validate(&self) -> Result<()> {
        if self.version != SKETCH_VERSION {
            return Err(invalid(format!(
                "sketch version {} is not supported (expected {SKETCH_VERSION})",
                self.version
            )));
        }
        if self.columns.is_empty() {
            return Err(invalid("the sketch has no columns".into()));
        }
        let mut seen = BTreeSet::new();
        for column in &self.columns {
            if !seen.insert(column.name.as_str()) {
                return Err(invalid(format!(
                    "column \"{}\" appears twice in the sketch",
                    column.name
                )));
            }
            if let ColumnKind::Categorical { values } = &column.kind {
                if values.is_empty() {
                    return Err(invalid(format!(
                        "category column \"{}\" lists no values",
                        column.name
                    )));
                }
            }
        }
        if self.classes.is_empty() {
            return Err(invalid("the sketch has no classes".into()));
        }
        if self.classes.iter().all(|c| c.size == 0) {
            return Err(invalid("every class has size 0".into()));
        }
        for class in &self.classes {
            if class.axes.len() != self.columns.len() {
                return Err(invalid(format!(
                    "class \"{}\" has {} axis entries for {} columns",
                    class.name,
                    class.axes.len(),
                    self.columns.len()
                )));
            }
            for (axis, column) in class.axes.iter().zip(&self.columns) {
                let at = format!("class \"{}\", column \"{}\"", class.name, column.name);
                let null_share = match axis {
                    Axis::Numeric { null_share, .. } | Axis::Categorical { null_share, .. } => {
                        *null_share
                    }
                };
                if !(0.0..=1.0).contains(&null_share) {
                    return Err(invalid(format!(
                        "{at}: the null share must be between 0 and 1"
                    )));
                }
                // An axis that is all nulls needs no usable weights.
                let needs_weights = null_share < 1.0;
                match (axis, &column.kind) {
                    (
                        Axis::Numeric {
                            min, max, density, ..
                        },
                        ColumnKind::Numeric { .. },
                    ) => {
                        if !(min.is_finite() && max.is_finite()) || min > max {
                            return Err(invalid(format!(
                                "{at}: the range needs a minimum that is not above its maximum"
                            )));
                        }
                        if needs_weights && !weights_ok(density) {
                            return Err(invalid(format!(
                                "{at}: the density needs at least one positive weight and no negative one"
                            )));
                        }
                    }
                    (Axis::Categorical { shares, .. }, ColumnKind::Categorical { values }) => {
                        if shares.len() != values.len() {
                            return Err(invalid(format!(
                                "{at}: {} shares for {} values",
                                shares.len(),
                                values.len()
                            )));
                        }
                        if needs_weights && !weights_ok(shares) {
                            return Err(invalid(format!(
                                "{at}: the shares need at least one positive weight and no negative one"
                            )));
                        }
                    }
                    _ => {
                        return Err(invalid(format!(
                            "{at}: the axis entry does not match the column's type"
                        )))
                    }
                }
            }
        }
        Ok(())
    }

    pub fn summary(&self) -> SketchSummary {
        SketchSummary {
            classes: self
                .classes
                .iter()
                .map(|c| ClassSummary {
                    name: c.name.clone(),
                    size: c.size,
                })
                .collect(),
        }
    }

    /// Replaces classes `a` and `b` with one class that stands for both: sizes add up, a number
    /// axis covers both ranges with the two densities laid over it, a category axis mixes the
    /// shares, all in proportion to the class sizes. The merged class takes the place of `a`.
    pub fn merge_classes(&mut self, a: usize, b: usize) -> Result<()> {
        if a == b || a >= self.classes.len() || b >= self.classes.len() {
            return Err(invalid("pick two different classes to merge".into()));
        }
        let (first, second) = (self.classes[a].clone(), self.classes[b].clone());
        let axes = first
            .axes
            .iter()
            .zip(&second.axes)
            .map(|(x, y)| merge_axes(x, first.size as f64, y, second.size as f64))
            .collect::<Result<Vec<Axis>>>()?;
        self.classes[a] = SketchClass {
            name: first.name,
            size: first.size + second.size,
            axes,
        };
        self.classes.remove(b);
        Ok(())
    }
}

/// Rows of a class that have a value on this axis.
fn present(size: f64, null_share: f64) -> f64 {
    size * (1.0 - null_share)
}

fn merge_axes(x: &Axis, size_x: f64, y: &Axis, size_y: f64) -> Result<Axis> {
    let total = size_x + size_y;
    let mixed_nulls = |nx: f64, ny: f64| {
        if total > 0.0 {
            (size_x * nx + size_y * ny) / total
        } else {
            0.0
        }
    };
    match (x, y) {
        (
            Axis::Numeric {
                min: min_x,
                max: max_x,
                density: density_x,
                null_share: nulls_x,
            },
            Axis::Numeric {
                min: min_y,
                max: max_y,
                density: density_y,
                null_share: nulls_y,
            },
        ) => {
            let (min, max) = (min_x.min(*min_y), max_x.max(*max_y));
            // The merged range can be much wider than either class's, so it gets at least
            // MERGED_BINS bins: with fewer, two far-apart classes would smear across the gap.
            let bins = density_x.len().max(density_y.len()).max(MERGED_BINS);
            let mut density = vec![0.0; bins];
            for (lo, hi, source, mass) in [
                (*min_x, *max_x, density_x, present(size_x, *nulls_x)),
                (*min_y, *max_y, density_y, present(size_y, *nulls_y)),
            ] {
                let sum: f64 = source.iter().sum();
                if sum <= 0.0 || mass <= 0.0 {
                    continue;
                }
                for (i, weight) in source.iter().enumerate() {
                    let share = mass * weight / sum;
                    let (from, to) = bin_edges(lo, hi, source.len(), i);
                    spread(&mut density, min, max, from, to, share);
                }
            }
            Ok(Axis::Numeric {
                min,
                max,
                density,
                null_share: mixed_nulls(*nulls_x, *nulls_y),
            })
        }
        (
            Axis::Categorical {
                shares: shares_x,
                null_share: nulls_x,
            },
            Axis::Categorical {
                shares: shares_y,
                null_share: nulls_y,
            },
        ) if shares_x.len() == shares_y.len() => {
            let normalized = |shares: &[f64], mass: f64| -> Vec<f64> {
                let sum: f64 = shares.iter().sum();
                shares
                    .iter()
                    .map(|s| if sum > 0.0 { mass * s / sum } else { 0.0 })
                    .collect()
            };
            let (nx, ny) = (
                normalized(shares_x, present(size_x, *nulls_x)),
                normalized(shares_y, present(size_y, *nulls_y)),
            );
            Ok(Axis::Categorical {
                shares: nx.iter().zip(&ny).map(|(p, q)| p + q).collect(),
                null_share: mixed_nulls(*nulls_x, *nulls_y),
            })
        }
        _ => Err(invalid(
            "the two classes do not describe the same columns".into(),
        )),
    }
}

fn bin_edges(min: f64, max: f64, bins: usize, i: usize) -> (f64, f64) {
    let width = (max - min) / bins as f64;
    (min + i as f64 * width, min + (i + 1) as f64 * width)
}

/// Adds `mass`, spread evenly over `from..to`, to the bins of `min..max` it overlaps.
fn spread(density: &mut [f64], min: f64, max: f64, from: f64, to: f64, mass: f64) {
    let bins = density.len();
    let width = (max - min) / bins as f64;
    if width <= 0.0 || to <= from {
        // A point mass (or a degenerate target range): it all lands in one bin.
        let at = if width > 0.0 {
            (((from - min) / width) as usize).min(bins - 1)
        } else {
            0
        };
        density[at] += mass;
        return;
    }
    for (i, slot) in density.iter_mut().enumerate() {
        let (lo, hi) = (min + i as f64 * width, min + (i + 1) as f64 * width);
        let overlap = (hi.min(to) - lo.max(from)).max(0.0);
        *slot += mass * overlap / (to - from);
    }
}

/// Index drawn in proportion to `weights` (which hold at least one positive weight).
fn draw(weights: &[f64], u: f64) -> usize {
    let total: f64 = weights.iter().sum();
    let mut left = u * total;
    let mut last_positive = 0;
    for (i, w) in weights.iter().enumerate() {
        if *w > 0.0 {
            last_positive = i;
            if left < *w {
                return i;
            }
            left -= w;
        }
    }
    last_positive
}

/// Samples `rows` rows from the sketch: one column of optional text values per sketch column.
/// The sketch must be valid ([`Sketch::validate`]).
pub fn generate(sketch: &Sketch, rows: usize, seed: u64) -> Vec<Vec<Option<String>>> {
    let mut rng = Rng::new(seed);
    let sizes: Vec<f64> = sketch.classes.iter().map(|c| c.size as f64).collect();
    let mut columns: Vec<Vec<Option<String>>> = sketch
        .columns
        .iter()
        .map(|_| Vec::with_capacity(rows))
        .collect();
    for _ in 0..rows {
        let class = &sketch.classes[draw(&sizes, rng.uniform())];
        for ((axis, column), out) in class.axes.iter().zip(&sketch.columns).zip(&mut columns) {
            // Three draws per cell whatever the outcome, so editing one axis never shifts the
            // random stream of the others.
            let (null_draw, pick, within) = (rng.uniform(), rng.uniform(), rng.uniform());
            out.push(match (axis, &column.kind) {
                (
                    Axis::Numeric {
                        min,
                        max,
                        density,
                        null_share,
                    },
                    ColumnKind::Numeric { integer },
                ) => (null_draw >= *null_share).then(|| {
                    let (from, to) = bin_edges(*min, *max, density.len(), draw(density, pick));
                    let value = (from + within * (to - from)).clamp(*min, *max);
                    if *integer {
                        format!("{}", value.round() as i64)
                    } else {
                        format!("{}", (value * 1e6).round() / 1e6)
                    }
                }),
                (Axis::Categorical { shares, null_share }, ColumnKind::Categorical { values }) => {
                    (null_draw >= *null_share).then(|| values[draw(shares, pick)].clone())
                }
                _ => None,
            });
        }
    }
    columns
}

// ---- proposing a sketch from the data

/// One prepared column as the sketch sees it.
enum Feature {
    Numeric {
        values: Vec<Option<f64>>,
        integer: bool,
    },
    Categorical {
        values: Vec<String>,
        cells: Vec<Option<usize>>,
    },
}

fn feature(p: &Prepared) -> Feature {
    let as_categories = |texts: Vec<Option<String>>, mut order: Vec<String>| {
        order.dedup();
        let cells = texts
            .iter()
            .map(|t| t.as_ref().and_then(|t| order.iter().position(|v| v == t)))
            .collect();
        Feature::Categorical {
            values: order,
            cells,
        }
    };
    match &p.merged {
        ColumnData::Categorical(values) => {
            let order: BTreeSet<&String> = values.iter().flatten().collect();
            as_categories(values.clone(), order.into_iter().cloned().collect())
        }
        ColumnData::Numeric(values) => {
            let mut distinct: Vec<f64> = values.iter().flatten().copied().collect();
            distinct.sort_by(f64::total_cmp);
            distinct.dedup();
            if p.integer && distinct.len() <= SMALL_DISTINCT {
                let text = |x: f64| format!("{x}");
                as_categories(
                    values.iter().map(|v| v.map(text)).collect(),
                    distinct.into_iter().map(text).collect(),
                )
            } else {
                Feature::Numeric {
                    values: values.clone(),
                    integer: p.integer,
                }
            }
        }
    }
}

/// Each row as a point: number columns scaled to 0..1 (a null sits at the column mean), category
/// columns one-hot and scaled so two different categories are at distance 1.
fn points(features: &[Feature], n: usize) -> Vec<Vec<f64>> {
    let mut rows = vec![Vec::new(); n];
    for f in features {
        match f {
            Feature::Numeric { values, .. } => {
                let present: Vec<f64> = values.iter().flatten().copied().collect();
                let (min, max) = present
                    .iter()
                    .fold((f64::INFINITY, f64::NEG_INFINITY), |(lo, hi), v| {
                        (lo.min(*v), hi.max(*v))
                    });
                let span = max - min;
                let scale = |v: f64| if span > 0.0 { (v - min) / span } else { 0.5 };
                let mean = if present.is_empty() {
                    0.5
                } else {
                    present.iter().map(|v| scale(*v)).sum::<f64>() / present.len() as f64
                };
                for (row, v) in rows.iter_mut().zip(values) {
                    row.push(v.map_or(mean, scale));
                }
            }
            Feature::Categorical { values, cells } => {
                let on = std::f64::consts::FRAC_1_SQRT_2;
                for (row, cell) in rows.iter_mut().zip(cells) {
                    row.extend((0..values.len()).map(|k| if *cell == Some(k) { on } else { 0.0 }));
                }
            }
        }
    }
    rows
}

fn distance(a: &[f64], b: &[f64]) -> f64 {
    a.iter().zip(b).map(|(x, y)| (x - y) * (x - y)).sum()
}

fn nearest(point: &[f64], centers: &[Vec<f64>], skip: Option<usize>) -> usize {
    let mut best = (usize::MAX, f64::INFINITY);
    for (i, center) in centers.iter().enumerate() {
        if Some(i) == skip {
            continue;
        }
        let d = distance(point, center);
        if d < best.1 {
            best = (i, d);
        }
    }
    best.0
}

fn centers_of(points: &[Vec<f64>], assignment: &[usize], k: usize) -> Vec<Vec<f64>> {
    let dims = points.first().map_or(0, Vec::len);
    let mut sums = vec![vec![0.0; dims]; k];
    let mut counts = vec![0usize; k];
    for (point, &class) in points.iter().zip(assignment) {
        counts[class] += 1;
        for (s, v) in sums[class].iter_mut().zip(point) {
            *s += v;
        }
    }
    for (sum, count) in sums.iter_mut().zip(&counts) {
        if *count > 0 {
            sum.iter_mut().for_each(|s| *s /= *count as f64);
        }
    }
    sums
}

/// Seeded k-means (k-means++ start, Lloyd's iterations). Returns a class index per row; classes
/// under `min_class_size` are folded, row by row, into the nearest remaining class.
fn group(points: &[Vec<f64>], k: usize, min_class_size: usize, seed: u64) -> Vec<usize> {
    let n = points.len();
    let k = k.clamp(1, n.max(1));
    let mut rng = Rng::new(seed);
    let mut centers = vec![points[((rng.uniform() * n as f64) as usize).min(n - 1)].clone()];
    while centers.len() < k {
        let nearest_distance: Vec<f64> = points
            .iter()
            .map(|p| distance(p, &centers[nearest(p, &centers, None)]))
            .collect();
        if nearest_distance.iter().sum::<f64>() <= 0.0 {
            break; // fewer distinct points than classes asked for
        }
        centers.push(points[draw(&nearest_distance, rng.uniform())].clone());
    }
    let mut assignment = vec![0usize; n];
    for _ in 0..KMEANS_ITERATIONS {
        let next: Vec<usize> = points.iter().map(|p| nearest(p, &centers, None)).collect();
        let changed = next != assignment;
        assignment = next;
        let updated = centers_of(points, &assignment, centers.len());
        let mut counts = vec![0usize; centers.len()];
        assignment.iter().for_each(|&a| counts[a] += 1);
        // An emptied class keeps its old centre; it simply has no rows.
        for ((center, new), count) in centers.iter_mut().zip(updated).zip(counts) {
            if count > 0 {
                *center = new;
            }
        }
        if !changed {
            break;
        }
    }
    // Fold the smallest undersized class until every class is large enough (or one is left).
    loop {
        let mut counts = vec![0usize; centers.len()];
        assignment.iter().for_each(|&a| counts[a] += 1);
        let alive: Vec<usize> = (0..centers.len()).filter(|&c| counts[c] > 0).collect();
        let smallest = alive.iter().copied().min_by_key(|&c| counts[c]);
        let Some(small) = smallest.filter(|&c| counts[c] < min_class_size && alive.len() > 1)
        else {
            break;
        };
        let live_centers: Vec<Vec<f64>> = centers_of(points, &assignment, centers.len());
        for (point, class) in points.iter().zip(assignment.iter_mut()) {
            if *class == small {
                let mut best = (usize::MAX, f64::INFINITY);
                for &c in alive.iter().filter(|&&c| c != small) {
                    let d = distance(point, &live_centers[c]);
                    if d < best.1 {
                        best = (c, d);
                    }
                }
                *class = best.0;
            }
        }
    }
    assignment
}

fn axis_for(f: &Feature, rows: &[usize], bins: usize) -> Axis {
    let null_share = |nulls: usize| {
        if rows.is_empty() {
            0.0
        } else {
            nulls as f64 / rows.len() as f64
        }
    };
    match f {
        Feature::Numeric { values, .. } => {
            let present: Vec<f64> = rows.iter().filter_map(|&r| values[r]).collect();
            if present.is_empty() {
                return Axis::Numeric {
                    min: 0.0,
                    max: 0.0,
                    density: vec![1.0],
                    null_share: 1.0,
                };
            }
            let (min, max) = present
                .iter()
                .fold((f64::INFINITY, f64::NEG_INFINITY), |(lo, hi), v| {
                    (lo.min(*v), hi.max(*v))
                });
            let mut density = vec![0.0; bins];
            let width = (max - min) / bins as f64;
            for v in &present {
                let bin = if width > 0.0 {
                    (((v - min) / width) as usize).min(bins - 1)
                } else {
                    0
                };
                density[bin] += 1.0;
            }
            Axis::Numeric {
                min,
                max,
                density,
                null_share: null_share(rows.len() - present.len()),
            }
        }
        Feature::Categorical { values, cells } => {
            let mut shares = vec![0.0; values.len()];
            let mut nulls = 0;
            for &r in rows {
                match cells[r] {
                    Some(k) => shares[k] += 1.0,
                    None => nulls += 1,
                }
            }
            Axis::Categorical {
                shares,
                null_share: null_share(nulls),
            }
        }
    }
}

fn validate_config(config: &SketchConfig) -> Result<()> {
    if config.classes < 1 {
        return Err(invalid("ask for at least 1 class".into()));
    }
    if config.min_class_size < 1 {
        return Err(invalid("the minimum class size must be at least 1".into()));
    }
    if config.bins < 1 {
        return Err(invalid("at least 1 density bin is needed".into()));
    }
    Ok(())
}

/// Groups the rows of `sample` into classes and describes each class on every column. Seeded and
/// deterministic. Identifier-like columns are dropped and rare categories merged first, by the
/// same rules as the other synthesizers.
pub fn propose(sample: &Sample, config: &SketchConfig) -> Result<Sketch> {
    validate_config(config)?;
    let Preparation { prepared, n, .. } = prepare(sample, &config.base)?;
    let features: Vec<Feature> = prepared.iter().map(feature).collect();
    let assignment = group(
        &points(&features, n),
        config.classes,
        config.min_class_size,
        config.base.seed,
    );
    let mut members: Vec<Vec<usize>> = Vec::new();
    let mut slot_of = std::collections::BTreeMap::new();
    for (row, class) in assignment.iter().enumerate() {
        let slot = *slot_of.entry(*class).or_insert_with(|| {
            members.push(Vec::new());
            members.len() - 1
        });
        members[slot].push(row);
    }
    // Largest class first; ties keep the order of first appearance.
    members.sort_by_key(|rows| std::cmp::Reverse(rows.len()));
    let sketch = Sketch {
        version: SKETCH_VERSION,
        columns: prepared
            .iter()
            .zip(&features)
            .map(|(p, f)| SketchColumn {
                name: p.name.clone(),
                kind: match f {
                    Feature::Numeric { integer, .. } => ColumnKind::Numeric { integer: *integer },
                    Feature::Categorical { values, .. } => ColumnKind::Categorical {
                        values: values.clone(),
                    },
                },
            })
            .collect(),
        classes: members
            .iter()
            .enumerate()
            .map(|(i, rows)| SketchClass {
                name: format!("Class {}", i + 1),
                size: rows.len(),
                axes: features
                    .iter()
                    .map(|f| axis_for(f, rows, config.bins))
                    .collect(),
            })
            .collect(),
    };
    Ok(sketch)
}

pub(crate) fn limitations() -> Vec<&'static str> {
    vec![
        "Inside a class every column is drawn on its own; a dependency between columns is kept only as far as the classes separate it.",
        "A sketch proposed from the data describes groups of real records, and its class ranges end at real values: handle the sketch like the data itself.",
        "If the sketch was changed by hand, the differences reported here include those changes.",
        "Numbers are drawn from a histogram over each class's range, so the shape inside a bin is uniform.",
        "Identifier-like columns and dates are dropped, not synthesized.",
    ]
}

/// Samples from `sketch` and measures the result against `sample`. The sketch may have been
/// changed by hand; every column it names must be a column the data can be compared on.
pub fn synthesize_sketch(
    sample: &Sample,
    sketch: &Sketch,
    config: &SynthesizeConfig,
) -> Result<SynthesisResult> {
    sketch.validate()?;
    let Preparation {
        prepared,
        mut dropped,
        merged_report,
        n,
        rows_excluded,
    } = prepare(sample, config)?;
    let mut kept: Vec<Prepared> = Vec::new();
    let mut by_name: std::collections::HashMap<String, Prepared> =
        prepared.into_iter().map(|p| (p.name.clone(), p)).collect();
    for column in &sketch.columns {
        let p = by_name.remove(&column.name).ok_or_else(|| {
            invalid(format!(
                "the sketch has a column \"{}\" that the data does not offer for synthesis",
                column.name
            ))
        })?;
        kept.push(p);
    }
    let mut unused: Vec<String> = by_name.into_keys().collect();
    unused.sort();
    dropped.extend(unused.into_iter().map(|column| DroppedColumn {
        column,
        reason: "not in the sketch".into(),
    }));

    let rows_out = config.rows.unwrap_or(n);
    let mut synthetic: Vec<ColumnData> = generate(sketch, rows_out, config.seed)
        .into_iter()
        .zip(&kept)
        .map(|(column, p)| match p.merged {
            ColumnData::Numeric(_) => ColumnData::Numeric(
                column
                    .into_iter()
                    .map(|v| v.and_then(|v| v.parse::<f64>().ok()))
                    .collect(),
            ),
            ColumnData::Categorical(_) => ColumnData::Categorical(column),
        })
        .collect();
    round_to_observed(&mut synthetic, &kept);
    let rows = format_rows(&synthetic, &kept, rows_out);

    let names: Vec<String> = kept.iter().map(|p| p.name.clone()).collect();
    let merged: Vec<ColumnData> = kept.iter().map(|p| p.merged.clone()).collect();
    let originals: Vec<ColumnData> = kept.iter().map(|p| p.original.clone()).collect();
    let report = SynthesisReport {
        version: REPORT_VERSION,
        method: "sketch",
        seed: config.seed,
        rows_in: n,
        rows_excluded,
        rows_out,
        columns_synthesized: names.clone(),
        columns_dropped: dropped.clone(),
        categories_merged: merged_report,
        correlation_shrinkage: 0.0,
        fidelity: metrics::fidelity(&names, &merged, &synthetic),
        leakage: metrics::leakage(&originals, &synthetic),
        privacy_statement: PRIVACY_STATEMENT,
        limitations: limitations(),
        warnings: dropped_warnings(&dropped),
        network: None,
        sketch: Some(sketch.summary()),
    };
    Ok(SynthesisResult {
        sample: Sample {
            headers: names,
            rows,
        },
        report,
    })
}

/// A sketch as text for a `.triplex.yaml`: a `sketch:` block next to the usual header.
pub fn sketch_to_yaml(sketch: &Sketch) -> Result<String> {
    #[derive(Serialize)]
    struct File<'a> {
        version: u32,
        sketch: &'a Sketch,
    }
    serde_yaml_ng::to_string(&File { version: 1, sketch }).map_err(|e| Error::Yaml(e.to_string()))
}

/// Reads the `sketch:` block of a `.triplex.yaml` text and validates it.
pub fn sketch_from_yaml(text: &str) -> Result<Sketch> {
    #[derive(Deserialize)]
    struct File {
        sketch: Option<Sketch>,
    }
    let file: File = serde_yaml_ng::from_str(text).map_err(|e| Error::Yaml(e.to_string()))?;
    let sketch = file
        .sketch
        .ok_or_else(|| invalid("the config has no `sketch:` block".into()))?;
    sketch.validate()?;
    Ok(sketch)
}

/// Reads `input_path` and proposes a sketch for it.
pub fn propose_file(input_path: &std::path::Path, config: &SketchConfig) -> Result<Sketch> {
    propose(&crate::read_rows(input_path)?, config)
}

/// Reads `input_path`, samples from `sketch`, writes the CSV to `output_path` and returns the report.
pub fn synthesize_sketch_file(
    input_path: &std::path::Path,
    output_path: &std::path::Path,
    sketch: &Sketch,
    config: &SynthesizeConfig,
) -> Result<SynthesisReport> {
    let sample = crate::read_rows(input_path)?;
    let result = synthesize_sketch(&sample, sketch, config)?;
    triplex_io::write_csv(output_path, &result.sample.headers, &result.sample.rows)?;
    Ok(result.report)
}

/// Byte-slice counterpart of [`propose_file`], for a caller with no filesystem (the browser).
pub fn propose_bytes(bytes: &[u8], extension: &str, config: &SketchConfig) -> Result<Sketch> {
    propose(
        &triplex_schemacast::read_full_bytes(bytes, extension)?,
        config,
    )
}

/// Byte-slice counterpart of [`synthesize_sketch_file`].
pub fn synthesize_sketch_bytes(
    bytes: &[u8],
    extension: &str,
    sketch: &Sketch,
    config: &SynthesizeConfig,
) -> Result<(Vec<u8>, SynthesisReport)> {
    let sample = triplex_schemacast::read_full_bytes(bytes, extension)?;
    let result = synthesize_sketch(&sample, sketch, config)?;
    let csv = triplex_io::write_csv_bytes(&result.sample.headers, &result.sample.rows)?;
    Ok((csv, result.report))
}
